Ltac split_cells H n H1 H2 :=
  lazymatch type of H with rw_cells ?sg ?m (?base + ?off) ?cs =>
    let l1 := eval cbv [firstn skipn] in (firstn n cs) in
    let l2 := eval cbv [firstn skipn] in (skipn n cs) in
    let k := eval cbv in (off + Z.of_nat (cells_size l1))%Z in
    destruct (proj1 (rw_cells_app sg m (base + off) l1 l2) H) as [H1 H2];
    replace (base + off + Z.of_nat (cells_size l1))%Z with (base + k)%Z in H2
      by (cbv [cells_size csize Z.of_nat Pos.of_succ_nat Pos.succ Pos.add Pos.mul Nat.add]; lia)
  end.

